// 这段JS演示 __dirname 和 __filename
// 实际在Node环境运行可看到真实路径
console.log('模拟输出:__dirname 和 __filename');

// 模拟 process.argv 的演示
var mock = ['/usr/bin/node','/app.js','name=小明','age=18'];
console.log('命令行参数:',mock);
console.log('脚本路径:',mock[1]);

// 🎯 在下面写你的 calc.js 代码!
// 运行: node calc.js add 3 5

var op = process.argv[2];
var a = parseFloat(process.argv[3]);
var b = parseFloat(process.argv[4]);

if (op === 'add') console.log(a + b);
else if (op === 'sub') console.log(a - b);
else if (op === 'mul') console.log(a * b);
else if (op === 'div') console.log(a / b);
else console.log('用法: node calc.js [add|sub|mul|div] num1 num2');

// 模块缓存演示
var count = 0;
console.log('模块被加载!', ++count);
// 第二次调用不会重置count,因为是缓存中的同一个对象

// 🎯 calculator.js
function add(a,b){return a+b}
function sub(a,b){return a-b}
function mul(a,b){return a*b}
function div(a,b){return a/b}

// 导出
// 然后在 index.js 中 require 并使用!
console.log('提示:在Node中新建两个文件试试!');
console.log('module.exports = { add, sub, mul, div };');

// 动态import在浏览器环境演示
// 注意:import()是异步的
console.log('演示: import() 用于按需加载');
import('data:text/javascript,export default 42').then(m => {
  console.log('动态导入结果:', m.default);
}).catch(e => console.log('运行环境不支持动态import'));

// path 模块演示(模拟)
